141	    const target = `${sessionId}.jsonl`;
142	    try {
143	      const entries = fs.readdirSync(dir, { withFileTypes: true });
144	      for (const entry of entries) {
145	        const fullPath = path.join(dir, entry.name);
146	        if (entry.isFile() && entry.name === target) return fullPath;
147	        if (entry.isDirectory()) {
148	          const result = findSessionFile(fullPath);
149	          if (result) return result;
150	        }
151	      }
152	    } catch {}
153	    return null;
154	  };
155	
156	  const sessionFile = findSessionFile(claudeDir);
157	  if (sessionFile) {
158	    fs.copyFileSync(sessionFile, sessionJsonlPath);
159	    found = true;
160	    process.stderr.write(`Found session JSONL at ${sessionFile}\n`);
161	    try {
162	      const content = fs.readFileSync(sessionFile, "utf8");
163	      sessionLines = content.split("\n").filter(l => l.trim());
164	    } catch {}
165	  }
166	
167	  if (!found) {
168	    const debugDirs = [];
169	    const walkForDebug = (d, depth) => {
170	      if (depth > 3 || !fs.existsSync(d)) return;
171	      try {
172	        const entries = fs.readdirSync(d, { withFileTypes: true });
173	        for (const entry of entries) {
174	          if (entry.isDirectory()) {
175	            debugDirs.push(path.join(d, entry.name));
176	            walkForDebug(path.join(d, entry.name), depth + 1);
177	          } else if (entry.name.endsWith(".jsonl")) {
178	            debugDirs.push(`  FILE: ${path.join(d, entry.name)}`);
179	          }
180	        }
181	      } catch {}
182	    };
183	    walkForDebug(claudeDir, 0);
184	    process.stderr.write(`Session JSONL not found for session_id=${sessionId}\n`);
185	    process.stderr.write(`Searched under: ${claudeDir}\n`);
186	    process.stderr.write(`Directory structure:\n${debugDirs.slice(0, 30).join("\n")}\n`);
187	  }
188	}
189	
190	// --- Build trace from session JSONL (rich per-turn events) ---
191	const events = [];
192	let evtIdx = 0;
193	const pushEvent = (kind, payload) => {
194	  evtIdx++;
195	  events.push({ id: `evt-${evtIdx}`, kind, ...payload });
196	};
197	const normalizeText = (value) => {
198	  if (typeof value === "string") return value;
199	  if (Array.isArray(value)) return value.map(normalizeText).join("\n");
200	  if (value && typeof value === "object") return JSON.stringify(value, null, 2);
201	  return "";
202	};
203	
204	const toolUseNames = {};
205	
206	for (const line of sessionLines) {
207	  let record;
208	  try {
209	    record = JSON.parse(line);
210	  } catch {
211	    continue;
212	  }
213	  const recordType = record.type;
214	  const ts = record.timestamp ?? null;
215	
216	  if (recordType === "assistant" && record.message?.content) {
217	    const content = record.message.content;
218	    const model = record.message.model ?? null;
219	    const turnUsage = record.message.usage ?? null;
220	    if (!Array.isArray(content)) continue;
221	    for (const block of content) {
222	      if (!block || typeof block !== "object") continue;
223	      const blockType = block.type;
224	      if (blockType === "thinking") {
225	        pushEvent("thinking", {
226	          role: "assistant",
227	          model,
228	          timestamp: ts,
229	          content: normalizeText(block.thinking ?? block.text ?? ""),
230	        });
231	      } else if (blockType === "text") {
232	        pushEvent("assistant_text", {
233	          role: "assistant",
234	          model,
235	          timestamp: ts,
236	          content: normalizeText(block.text ?? ""),
237	        });
238	      } else if (blockType === "tool_use") {
239	        const toolName = block.name ?? "unknown_tool";
240	        toolUseNames[block.id] = toolName;
241	        pushEvent("tool_use", {
242	          role: "assistant",
243	          model,
244	          timestamp: ts,
245	          name: toolName,
246	          toolUseId: block.id ?? null,
247	          input: block.input ?? null,
248	        });
249	      }
250	    }
251	  } else if (recordType === "tool_result" && record.toolUseResult) {
252	    const result = record.toolUseResult;
253	    const toolUseId = result.tool_use_id ?? null;
254	    pushEvent("tool_result", {
255	      role: "tool",
256	      timestamp: ts,
257	      toolUseId,
258	      toolName: toolUseNames[toolUseId] ?? null,
259	      isError: result.is_error ?? false,
260	      content: normalizeText(result.content ?? ""),
261	    });
262	  } else if (recordType === "user" && record.message?.content) {
263	    const userContent = record.message.content;
264	    if (Array.isArray(userContent)) {
265	      for (const block of userContent) {
266	        if (!block || typeof block !== "object") continue;
267	        if (block.type === "tool_result") {
268	          const toolUseId = block.tool_use_id ?? null;
269	          const resultContent = Array.isArray(block.content)
270	            ? block.content.map(c => normalizeText(c.text ?? c.content ?? c)).join("\n")
271	            : normalizeText(block.content ?? "");
272	          pushEvent("tool_result", {
273	            role: "tool",
274	            timestamp: ts,
275	            toolUseId,
276	            toolName: toolUseNames[toolUseId] ?? null,
277	            isError: block.is_error ?? false,
278	            content: resultContent,
279	          });
280	        }
281	      }
282	    } else if (typeof userContent === "string") {
283	      pushEvent("user_message", {
284	        role: "user",
285	        timestamp: ts,
